{
  "up": "Select molecule_chembl_id AS compound_chembl_id, canonical_smiles, compound_key, pubmed_id_or_doi, assay_description, standard_type, standard_relation, standard_value, standard_units, activity_comment, target_chembl_id, target_name, target_organism From molecule_dictionary MD Join activities ACT ON MD.molregno = ACT.molregno Join assays ASY ON ACT.assay_id = ASY.assay_id Join target_dictionary TD ON ASY.tid = TD.tid Join compound_structures CS ON MD.molregno = CS.molregno Join docs DOC ON ACT.doc_id = DOC.doc_id Where ASY.assay_organism = 'Homo sapiens' And ASY.chembl_id = 'CHEMBL333' And ACT.bao_endpoint = 'IC50' And ACT.standard_type = 'IC50' And ACT.standard_relation = '=' And ACT.standard_value IS NOT NULL And ACT.standard_units IS NOT NULL And ACT.pubmed_id IS NOT NULL Or ACT.doi IS NOT NULL Order By compound_chembl_id, canonical_smiles, compound_key, pubmed_id_or_doi, assay_description, standard_type, standard_relation, standard_value, standard_units, activity_comment, target_chembl_id, target_name, target_organism"
}
